customCSS:
.t, .history { color: #697098; }
.join { color: #c3e88d; }
.part, .quit { color: #697098; }
.kick, .error { color: #ff5370; }
.notice { color: #ffcb6b; }
.action { color: #c792ea; }
.mode, .nick, .topic, .server { color: #89ddff; }
.highlight { color: #bfc7d5; background-color: #3e4452; border-left: 3px solid #c792ea; padding-left: 8px; }
.reply { color: #697098; border-left: 2px solid #82b1ff; padding-left: 6px; }
.oper { color: #292d3e; background-color: #ffcb6b; }
.reactions { color: #82b1ff; background-color: #2c323c; }
.card { background-color: #2c323c; border-color: #697098; }
.card-title { color: #82b1ff; }
.card-desc { color: #697098; }
.daychange { color: #697098; border-color: #2c323c; }
